    /**
     * Tests creating a new PaymentMethod.
     *
     * @return    PaymentMethod
     */
    public PaymentMethod testCreate() throws Throwable {
    PaymentMethod entity = null;

    LOGGER.info( "PaymentMethodTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a PaymentMethod");

    StringBuilder msg = new StringBuilder( "-- Failed to create a PaymentMethod" );

    try {
        entity = service.createPaymentMethod( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getPaymentMethodId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a PaymentMethod with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a PaymentMethod.
     *
     * @return    PaymentMethod
     */
    public PaymentMethod testRead() throws Throwable {
    LOGGER.info( "PaymentMethodTest:testRead()" );
    LOGGER.info( "-- Reading a previously created PaymentMethod" );

    PaymentMethod entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read PaymentMethod with primary key" );
    msg.append( theId );

    try {
        entity = service.getPaymentMethod( new PaymentMethodFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getPaymentMethodId();

        LOGGER.info( "-- Successfully found PaymentMethod " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a PaymentMethod.
     *
     * @return    PaymentMethod
     */
    public PaymentMethod testUpdate() throws Throwable {
    LOGGER.info( "PaymentMethodTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a PaymentMethod." );

    StringBuilder msg = new StringBuilder( "Failed to update a PaymentMethod : " );
    PaymentMethod entity = null;

    try {
        UpdatePaymentMethodCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setPaymentMethodId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created PaymentMethod." );

        entity = service.updatePaymentMethod( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved PaymentMethod - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a PaymentMethod.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "PaymentMethodTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created PaymentMethod." );

    try {
        DeletePaymentMethodCommand deleteCommand = new DeletePaymentMethodCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted PaymentMethod with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete PaymentMethod with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all PaymentMethods.
     *
     * @return    Collection
     */
    public List<PaymentMethod> testGetAll() throws Throwable {
    LOGGER.info( "PaymentMethodTest:testGetAll() - Retrieving Collection of PaymentMethods:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PaymentMethod : " );
    List<PaymentMethod> collection  = null;

    try {
        // call the static get method on the PaymentMethodService
        collection = service.getAllPaymentMethod();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PaymentMethod currEntity  = null;
            Iterator<PaymentMethod> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPaymentMethodId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

